formulas.expression:
OR(
AND(
    ISPICKVAL({!recordId.WI_ProcessType__c}, 'Wealth & Investment'),
    {!recordId.RecordType.DeveloperName} = 'WI_ClientEngagementReportAddendum',
    OR({!isRM}, {!isAM})
),
AND(
    ISPICKVAL({!recordId.WI_ProcessType__c}, 'Wealth & Investment'),
    {!recordId.RecordType.DeveloperName} = 'WI_ClientEngagementReport',
    {!isRM}
),
AND(
    ISPICKVAL({!recordId.WI_ProcessType__c}, 'Wealth Only'),
    {!recordId.RecordType.DeveloperName} = 'WI_ClientEngagementReportAddendum',
    OR({!isWM}, {!isWA})
),
AND(
    ISPICKVAL({!recordId.WI_ProcessType__c}, 'Wealth Only'),
    {!recordId.RecordType.DeveloperName} = 'WI_ClientEngagementReport',
    {!isWM}
)
)
